// Orquestacion: serializar registros validos a JSON para un INSERT en bloque (jsonb_to_recordset). Sin transformaciones de negocio (esas quedan en Postgres).
const records = $('Validar (id y date presentes)').all().map(i => i.json);
const received = $('Socrata: fetch ventana').all().length;
const failed = received - records.length;
const config = $('Ventana dev (1 mes)').first().json;
// El payload viaja como literal SQL: comillas + escape de apóstrofes ('' -> '').
const payloadSql = "'" + JSON.stringify(records).replace(/'/g, "''") + "'";
return [{
  json: {
    payloadSql,
    received,
    valid: records.length,
    failed,
    windowStart: config.windowStart,
    windowEnd: config.windowEnd,
    status: failed > 0 ? 'PARTIAL' : 'SUCCESS',
    finishedAt: new Date().toISOString()
  }
}];

